import { useLayoutEffect, useRef, useState } from 'react';
import Interpretation from './Interpretation.jsx';

// Animate a sent message out of the composer: it starts at the text box's position and size,
// then settles into the chat as a bar.
function morph(el, from) {
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const to = el.getBoundingClientRect();
  if (!to.width || !to.height) return;
  el.animate([
    { transformOrigin: 'top left', opacity: 0.6,
      transform: `translate(${from.left - to.left}px,${from.top - to.top}px) scale(${from.width / to.width},${from.height / to.height})` },
    { transformOrigin: 'top left', transform: 'none', opacity: 1 },
  ], { duration: 420, easing: 'cubic-bezier(.2,.8,.2,1)' });
}

function ManualForm({ busy, onSubmit }) {
  return (
    <form id="manual-form" onSubmit={e => { e.preventDefault(); onSubmit(new FormData(e.currentTarget)); }}>
      <div className="form-grid">
        <label>Income retained (%)<input name="income" type="number" min="0" max="150" defaultValue="100" step="0.1" required /></label>
        <label>Household bills change (%)<input name="bills" type="number" min="-50" max="200" defaultValue="0" step="0.1" required /></label>
        <label>One-off expense ($)<input name="oneoff" type="number" min="0" max="1000000" defaultValue="0" step="0.01" required /></label>
        <label>Assessment duration (months)<input name="duration" type="number" min="1" max="60" defaultValue="6" required /></label>
        <label>Recurring adjustment ($/month)<input name="recurring" type="number" min="-1000000" max="1000000" defaultValue="0" step="0.01" required /></label>
        <label>Adjustment label<input name="label" defaultValue="User-supplied expense" maxLength="100" required /></label>
      </div>
      <small>Enter only the change in recurring spending, not the existing category budget. All changes are held constant over this duration.</small>
      <button type="submit" disabled={busy}>Review manual scenario</button>
    </form>
  );
}

export default function ChatPanel({ c }) {
  const [query, setQuery] = useState('');
  const listRef = useRef(null);
  const queryRef = useRef(null);

  // Keep the newest message in view; a just-sent message animates out of the text box.
  useLayoutEffect(() => {
    const list = listRef.current;
    const last = c.messages.at(-1);
    if (!list || !last) return;
    if (last.morphFrom) {
      list.scrollTop = list.scrollHeight;
      morph(list.lastElementChild, last.morphFrom);
    } else {
      list.scrollTo({ top: list.scrollHeight, behavior: 'smooth' });
    }
  }, [c.messages.length]); // eslint-disable-line react-hooks/exhaustive-deps

  function send(e) {
    e.preventDefault();
    const text = query.trim();
    if (c.busy || !c.baseline || !text) return;
    const r = queryRef.current.getBoundingClientRect();
    setQuery('');
    c.sendQuery(text, { left: r.left, top: r.top, width: r.width, height: r.height });
  }

  function onKeyDown(e) {
    if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
      e.preventDefault();
      e.currentTarget.form.requestSubmit();
    }
  }

  function reuse(q) {
    if (c.busy) return;
    setQuery(q);
    queryRef.current.focus();
  }

  return (
    <section className="chat-panel">
      <div className="panel-heading">
        <div>
          <h2>Describe a change</h2>
          <p>Plain language in. Clear assumptions out.</p>
        </div>
      </div>
      <div id="messages" className="messages" aria-live="polite" ref={listRef}>
        {c.messages.map(m => (m.kind === 'interp'
          ? <Interpretation key={m.id} msg={m} busy={c.busy} onClarify={c.clarify} onApply={c.applyScenario} />
          : <div key={m.id} className={'message' + (m.user ? ' user' : '')}>{m.text}</div>))}
      </div>
      <div className="examples" id="recent-queries" aria-label="Recent queries" hidden={!c.recentQueries.length}>
        {c.recentQueries.map(q => (
          <button key={q} type="button" title={q} aria-label={'Reuse query: ' + q} disabled={c.busy} onClick={() => reuse(q)}>
            <span className="recent-query-text">{q}</span><span aria-hidden="true">↗</span>
          </button>
        ))}
      </div>
      <form id="chat-form" onSubmit={send}>
        <label className="sr-only" htmlFor="query">Describe your financial shock</label>
        <textarea id="query" ref={queryRef} maxLength="500" rows="3" required disabled={c.busy}
          placeholder="What if groceries rise 10%, or I lose my income for six months?"
          value={query} onChange={e => setQuery(e.target.value)} onKeyDown={onKeyDown} />
        <div className="composer-footer">
          <small>Estimates stay labelled. You review before applying.</small>
          <button id="send" type="submit" disabled={c.busy}>{c.busy ? 'Working…' : 'Interpret ↗'}</button>
        </div>
      </form>
      <details className="manual" open={c.manualOpen} onToggle={e => c.setManualOpen(e.currentTarget.open)}>
        <summary>Use manual scenario controls</summary>
        <ManualForm busy={c.busy} onSubmit={c.submitManual} />
      </details>
    </section>
  );
}

import { describeChanges } from '../format.js';

function Question({ q }) {
  switch (q.kind) {
    case 'monthly_cost':
      return <label>{q.question}<input type="number" name={`amount_${q.key}`} min="0" max="1000000" step="0.01" required placeholder="Monthly amount in CAD" /></label>;
    case 'income_percentage':
      return <label>{q.question}<input type="number" name="incomePct" min="0" max="150" step="0.1" required placeholder="0 for no income, 55 for 55%" /></label>;
    case 'duration':
      return <label>{q.question}<input type="number" name="duration" min="1" max="60" step="1" required /></label>;
    case 'confirmation':
      return <label className="check"><input type="checkbox" name="overlap" required /> {q.question}</label>;
    default:
      return <p className="error">Please revise your message: {q.question}</p>;
  }
}

// The assistant's reading of a scenario: either questions to answer, or a summary to review and apply.
export default function Interpretation({ msg, busy, onClarify, onApply }) {
  const r = msg.result;
  const needsInput = r.status === 'needs_input';
  const rephrase = needsInput && r.questions.some(q => q.kind === 'rephrase');

  return (
    <div className="message">
      <p><strong>{needsInput ? 'A little more detail' : 'Review your scenario'}</strong></p>
      <p>{r.interpretation || 'Please review the changes and assumptions below.'}</p>
      {r.status === 'ok' && r.shock && (
        <ul className="changes">{describeChanges(r.shock).map(x => <li key={x}>{x}</li>)}</ul>
      )}
      {r.assumptions?.length > 0 && <ul>{r.assumptions.map(a => <li key={a}>{a}</li>)}</ul>}
      {needsInput ? (
        <form className="clarify" onSubmit={e => { e.preventDefault(); onClarify(msg, new FormData(e.currentTarget)); }}>
          {r.questions.map((q, i) => <Question key={q.key ?? i} q={q} />)}
          {!rephrase && !msg.done && <button type="submit" disabled={busy}>Use these values →</button>}
        </form>
      ) : (
        <>
          <details><summary>See exact scenario inputs</summary><pre>{JSON.stringify(r.shock, null, 2)}</pre></details>
          {!msg.done && <button type="button" disabled={busy} onClick={() => onApply(msg)}>Apply this scenario ↗</button>}
        </>
      )}
    </div>
  );
}

import { cash, runway } from '../format.js';
import ActionPlan from './ActionPlan.jsx';

function Chart({ plan }) {
  const n = plan.duration_assessment.months;
  const a = plan.after_shock;
  const vals = Array.from({ length: n + 1 }, (_, i) => a.buffer + i * (a.income - a.spending));
  const hi = Math.max(1, ...vals);
  const lo = Math.min(0, ...vals);
  const y = v => 20 + ((hi - v) / (hi - lo)) * 110;
  const x = i => 20 + (i / n) * 360;
  return (
    <div className="chart">
      <h3>Buffer through the scenario</h3>
      <small>Approximation from rounded API values. Negative values represent unfunded spending, not approved borrowing.</small>
      <svg viewBox="0 0 400 165" role="img" aria-label={`Projected buffer over ${n} months`}>
        <line x1="20" y1={y(0)} x2="380" y2={y(0)} stroke="#cbd6ca" strokeDasharray="4" />
        <polyline points={vals.map((v, i) => `${x(i)},${y(v)}`).join(' ')} fill="none" stroke="#1c594b" strokeWidth="3" />
        <circle cx="380" cy={y(vals[n])} r="4" fill="#f0854e" />
        <text x="20" y="157" fontSize="10" fill="#65746d">Now</text>
        <text x="325" y="157" fontSize="10" fill="#65746d">Month {n}</text>
      </svg>
    </div>
  );
}

function Explanation({ state }) {
  let body;
  if (!state || state.loading) body = <p>Preparing the explanation…</p>;
  else if (state.error) body = `Calculations are available. Explanation unavailable: ${state.error}`;
  else {
    const t = state.data;
    body = (
      <>
        <h3>What this means</h3><p>{t.summary}</p>
        <h3>Your goal</h3><p>{t.goal_plan_text}</p>
        <h3>Contingency plan</h3><p>{t.backup_plan_text}</p>
        {t.caveat && <p className="warning">{t.caveat}</p>}
        <small>Explanation source: {t.source}</small>
      </>
    );
  }
  return <div id="explanation" className="explanation">{body}</div>;
}

const Mini = ({ label, value }) => <div className="mini"><small>{label}</small><strong>{value}</strong></div>;

// Children stay direct descendants of #results: the Plan view's CSS hides all but .action-plans and .explanation.
function PlanResults({ c }) {
  const p = c.plan;
  const b = c.baseline;
  const a = p.after_shock;
  const d = p.duration_assessment;
  const rows = [
    ['Monthly inflows', cash(p.baseline.income), cash(a.income)],
    ['Monthly spending', cash(p.baseline.spending), cash(a.spending)],
    ['Buffer after immediate costs', cash(p.baseline.buffer), cash(a.buffer)],
    ['Monthly shortfall', cash(Math.max(b.spending - b.income, 0)), cash(a.monthly_gap)],
    ['Runway', runway(p.baseline), runway(a)],
    ['Immediate expense', '—', cash(a.one_off_costs || 0)],
  ];
  return (
    <>
      <table className="comparison">
        <thead><tr><th>Account {c.account}</th><th>Before</th><th>After</th></tr></thead>
        <tbody>{rows.map(r => <tr key={r[0]}><td>{r[0]}</td><td>{r[1]}</td><td>{r[2]}</td></tr>)}</tbody>
      </table>
      {d && (
        <div className={'outcome' + (d.covers_duration ? '' : ' danger')}>
          <h3>{d.covers_duration ? 'Covered' : 'Funding gap'} over {d.months} months</h3>
          <p>{d.assumption}</p>
          <div className="mini-grid">
            <Mini label="Required starting buffer" value={cash(d.required_starting_buffer)} />
            <Mini label="Additional buffer needed" value={cash(d.additional_buffer_needed)} />
          </div>
        </div>
      )}
      {d && <Chart plan={p} />}
      <div className="mini-grid">
        <Mini label="Required monthly spending reduction" value={cash(p.backup_plan.monthly_cut_needed)} />
        <Mini label="Immediate funding needed" value={cash(p.backup_plan.upfront_funding_needed)} />
        <Mini label="Emergency-fund target" value={cash(p.goal_plan.target_amount)} />
        <Mini label="Time to goal at baseline surplus" value={p.goal_plan.months_to_goal === null ? 'Not reachable' : p.goal_plan.months_to_goal + ' months'} />
      </div>
      {p.action_plan && (
        <ActionPlan key={c.planVersion} plan={p} planning={c.planning} busy={c.busy} error={c.planningError} onSubmit={c.recalculatePlan} />
      )}
      <Explanation state={c.explanation} />
      <details className="data">
        <summary>Inspect all calculated values and account data</summary>
        <pre>{JSON.stringify({ account: b, plan: p }, null, 2)}</pre>
      </details>
      <p style={{ fontSize: 10, color: 'var(--muted)' }}>Amounts are displayed as whole dollars. Estimates are scenario inputs, not observed category budgets.</p>
    </>
  );
}

export default function ResultsPanel({ c }) {
  return (
    <section className={'results-panel' + (c.plan ? ' revealed' : '')}>
      <div className="panel-heading">
        <div>
          <h2>See the impact</h2>
