import puppeteer from 'puppeteer-core';
const out = process.argv[2];
const browser = await puppeteer.launch({ executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', headless: 'new', defaultViewport: { width: 1400, height: 900 } });
const page = await browser.newPage();
const errors = [];
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:5173/', { waitUntil: 'networkidle0' });
await page.click('#enter-app');
await page.waitForSelector('#user-database:not([hidden])', { timeout: 5000 });
await page.waitForFunction(() => document.querySelectorAll('.account-card').length > 0);
console.log('users view:', await page.$eval('#user-count', e => e.textContent));
await page.screenshot({ path: out + '/1-users.png' });
await page.type('#user-search', '20134');
await page.click('.account-card');
await page.waitForFunction(() => document.body.dataset.view === 'customer' && document.querySelector('.metric'));
console.log('metrics:', await page.$$eval('.metric strong', els => els.map(e => e.textContent).join(' | ')));
await page.screenshot({ path: out + '/2-customer.png' });
await page.click('.cushion-tabs button:nth-child(3)');
await page.waitForFunction(() => document.body.dataset.view === 'stress');
console.log('results hidden before apply:', await page.$eval('.results-panel', e => getComputedStyle(e).display === 'none'));
await page.click('.manual summary');
await page.$eval('#manual-form input[name=income]', e => { e.value = ''; });
await page.type('#manual-form input[name=income]', '55');
await page.click('#manual-form button[type=submit]');
await page.waitForFunction(() => document.querySelector('ul.changes'));
console.log('changes:', await page.$$eval('ul.changes li', els => els.map(e => e.textContent).join(' / ')));
await page.screenshot({ path: out + '/3-review.png' });
await page.evaluate(() => [...document.querySelectorAll('.message button')].find(b => b.textContent.includes('Apply')).click());
await page.waitForFunction(() => document.querySelector('.results-panel.revealed .comparison'), { timeout: 10000 });
await page.waitForFunction(() => !document.querySelector('#explanation')?.textContent.includes('Preparing'), { timeout: 30000 }).catch(() => {});
console.log('apply button removed:', !(await page.evaluate(() => [...document.querySelectorAll('.message button')].some(b => b.textContent.includes('Apply')))));
console.log('last message:', await page.$eval('#messages .message:last-child', e => e.textContent));
console.log('explanation:', (await page.$eval('#explanation', e => e.textContent)).slice(0, 120));
await page.screenshot({ path: out + '/4-applied.png', fullPage: true });
await page.click('.cushion-tabs button:nth-child(4)');
await page.waitForFunction(() => document.body.dataset.view === 'plan');
const before = await page.$eval('.plan-numbers dd', e => e.textContent);
await page.$eval('input[name=target_months]', e => { e.value = ''; });
await page.type('input[name=target_months]', '6');
await page.click('#planning-form button[type=submit]');
await page.waitForFunction(b => document.querySelector('.plan-numbers dd').textContent !== b, { timeout: 10000 }, before);
console.log('plan target buffer:', before, '->', await page.$eval('.plan-numbers dd', e => e.textContent));
await page.screenshot({ path: out + '/5-plan.png' });
// Chat: Enter sends and the user's message becomes a bar.
await page.click('.cushion-tabs button:nth-child(3)');
await page.type('#query', 'What if groceries rise 10%?');
await page.keyboard.press('Enter');
await page.waitForFunction(() => [...document.querySelectorAll('.message.user')].some(e => e.textContent.includes('groceries')));
console.log('textarea cleared:', await page.$eval('#query', e => e.value === ''));
await page.waitForFunction(() => !document.querySelector('#send').disabled, { timeout: 30000 }).catch(() => {});
console.log('chat panel height == viewport-32:', await page.$eval('.chat-panel', e => Math.round(e.getBoundingClientRect().height)));
await page.screenshot({ path: out + '/6-chat.png' });
console.log('errors:', errors.length ? errors : 'none');
await browser.close();
